const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

// Minimal external heartbeat: GET the target URL, fail the canary run on
// any non-2xx/3xx status or a request error. TARGET_URL is injected as a
// canary environment variable (infra/modules/synthetic-probe/main.tf) so
// this script has no hardcoded endpoint.
const apiCanaryBlueprint = async function () {
    const targetUrl = process.env.TARGET_URL;
    if (!targetUrl) {
        throw new Error('TARGET_URL environment variable is not set');
    }

    const parsed = new URL(targetUrl);
    const isHttps = parsed.protocol === 'https:';

    const requestOptions = {
        hostname: parsed.hostname,
        method: 'GET',
        path: parsed.pathname || '/',
        port: parsed.port || (isHttps ? 443 : 80),
        protocol: parsed.protocol,
    };

    const stepConfig = {
        includeRequestHeaders: false,
        includeResponseHeaders: false,
        includeRequestBody: false,
        includeResponseBody: false,
        restrictedHeaders: [],
        continueOnHttpStepFailure: false,
    };

    await synthetics.executeHttpStep('externalHeartbeat', requestOptions, null, stepConfig);
};

exports.handler = async () => {
    return await apiCanaryBlueprint();
};
